import{_ as a,o as s,c as i,aO as t}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"Linux 应用快捷方式：.desktop 文件规范与手动创建","description":"","frontmatter":{"date":"2026-11-16T12:00:00.000Z","title":"Linux 应用快捷方式：.desktop 文件规范与手动创建","source":[["1-知识/工具/Linux环境/Ubuntu 创建应用快捷方式"]],"tags":["工具","教程手册","Linux"],"categories":["工具"],"permalink":"/pages/56ec4b"},"headers":[],"relativePath":"工具/Linux 应用快捷方式：.desktop 文件规范与手动创建.md","filePath":"工具/Linux 应用快捷方式：.desktop 文件规范与手动创建.md","lastUpdated":1794797791000}'),n={name:"工具/Linux 应用快捷方式：.desktop 文件规范与手动创建.md"};function d(p,e,l,o,r,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="linux-应用快捷方式-desktop-文件规范与手动创建" tabindex="-1">Linux 应用快捷方式：.desktop 文件规范与手动创建 <a class="header-anchor" href="#linux-应用快捷方式-desktop-文件规范与手动创建" aria-label="Permalink to &quot;Linux 应用快捷方式：.desktop 文件规范与手动创建&quot;">​</a></h1> <p>Linux 桌面环境的应用列表由 <code>.desktop</code> 文件驱动。解压版 IDE、自编译程序这类不经过包管理器安装的应用不会自动出现在应用列表里，需要手动创建 <code>.desktop</code> 文件注册。本文记录完整的创建步骤与常用字段规范，适用于 GNOME、KDE 等遵循 freedesktop 规范的桌面环境。</p> <h2 id="基本步骤" tabindex="-1">基本步骤 <a class="header-anchor" href="#基本步骤" aria-label="Permalink to &quot;基本步骤&quot;">​</a></h2> <p>以一个解压到 <code>/develop/application</code> 的应用为例。</p> <h3 id="_1-选择存放目录" tabindex="-1">1. 选择存放目录 <a class="header-anchor" href="#_1-选择存放目录" aria-label="Permalink to &quot;1. 选择存放目录&quot;">​</a></h3> <p><code>.desktop</code> 文件有两个标准位置：</p> <ul><li><code>/usr/share/applications/</code>——系统级，所有用户可见，修改需要 root 权限；</li> <li><code>~/.local/share/applications/</code>——用户级，仅当前用户可见，无需 sudo，推荐个人使用场景优先选这里。</li></ul> <h3 id="_2-创建并编辑文件" tabindex="-1">2. 创建并编辑文件 <a class="header-anchor" href="#_2-创建并编辑文件" aria-label="Permalink to &quot;2. 创建并编辑文件&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/applications/application.desktop</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>写入内容：</p> <div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Desktop Entry]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=IntelliJ IDEA</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Comment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Java IDE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/develop/application/bin/application.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/develop/application/bin/application.png</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Application</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Categories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Development</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">;IDE;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_3-添加执行权限" tabindex="-1">3. 添加执行权限 <a class="header-anchor" href="#_3-添加执行权限" aria-label="Permalink to &quot;3. 添加执行权限&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/applications/application.desktop</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>部分桌面环境（尤其 GNOME/Wayland）要求 <code>.desktop</code> 文件带可执行权限才信任并显示；放到 applications 目录的场景多数环境不强制，但加上没有坏处。</p> <p>保存后应用列表通常立即或重新登录后出现对应条目。若未生效，可执行 <code>update-desktop-database ~/.local/share/applications/</code> 刷新缓存。</p> <h2 id="字段说明" tabindex="-1">字段说明 <a class="header-anchor" href="#字段说明" aria-label="Permalink to &quot;字段说明&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>字段</th> <th>作用</th> <th>备注</th></tr></thead> <tbody><tr><td><code>Name</code></td> <td>应用列表中显示的名称</td> <td>必填</td></tr> <tr><td><code>Exec</code></td> <td>启动命令，指向可执行文件或启动脚本</td> <td>必填；带空格的路径需引号或转义</td></tr> <tr><td><code>Type</code></td> <td>条目类型，应用固定为 <code>Application</code></td> <td>必填；其余合法值 <code>Link</code>（链接）、<code>Directory</code>（目录项）</td></tr> <tr><td><code>Icon</code></td> <td>图标文件路径</td> <td>png/svg 均可，也可写图标主题名</td></tr> <tr><td><code>Comment</code></td> <td>悬浮提示说明</td> <td>可选</td></tr> <tr><td><code>Terminal</code></td> <td>是否在终端窗口中运行</td> <td>CLI 程序设 <code>true</code>，GUI 程序设 <code>false</code></td></tr> <tr><td><code>Categories</code></td> <td>应用分类，影响列表分组与搜索</td> <td>多值用分号分隔，如 <code>Development;Utility;</code></td></tr></tbody></table> <p>两个容易踩的点：</p> <ul><li><strong><code>Encoding=UTF-8</code> 已废弃</strong>。早期教程常带这一行，但 freedesktop 桌面项规范已将其标记为 deprecated——UTF-8 是唯一合法编码，无需显式声明，新文件直接省略。</li> <li><strong><code>Exec</code> 不走登录 shell</strong>。启动脚本若依赖 PATH、环境变量（如 <code>~/.bashrc</code> 里配置的 <code>JAVA_HOME</code>），在 <code>.desktop</code> 里可能失效，脚本内应使用绝对路径或自行 source 环境。</li></ul> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>手动安装的应用注册进应用列表，核心就是三步：选目录（系统级 <code>/usr/share/applications</code> 或用户级 <code>~/.local/share/applications</code>）、写 <code>[Desktop Entry]</code>（Name/Exec/Type 三必填）、加执行权限。字段规范以 <a href="https://specifications.freedesktop.org/desktop-entry-spec/latest/" target="_blank" rel="noreferrer">freedesktop Desktop Entry Specification</a> 为准，网上教程里的 <code>Encoding</code> 字段可以放心删掉。</p>`,38)])])}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
